-- crash-edit/update-person
-- Saves a person's facts only if nobody changed them since the editor loaded them (the `version` must match). Raises the version.
--
-- Parameters, with the example values used to render this file:
--   $1 = "killed"
--   $2 = "Example Person"
--   $3 = null
--   $4 = 34
--   $5 = "female"
--   $6 = "passenger"
--   $7 = "Example village"
--   $8 = "public"
--   $9 = "draft"
--   $10 = "0199c8a0-0000-7000-8000-00000000000a"
--   $11 = 1
--
-- Generated by `pnpm db:queries` from lib/db/queries/crash-edit.ts. Do not edit by hand.

update "persons"
set "status" = $1, "name_en" = $2, "name_np" = $3, "age" = $4, "sex" = $5, "road_user" = $6, "hometown_text" = $7, "name_visibility" = $8, "publication" = $9, "version" = "persons"."version" + 1, "updated_at" = now()
where ("persons"."id" = $10
  and "persons"."version" = $11)
returning "id", "crash_id", "slug", "status", "name_en", "name_np", "age", "sex", "road_user", "hometown_text", "name_visibility", "publication", "version", "created_at", "updated_at";
